<?php
namespace App\Services;use App\Models\TrainingProgram;class TrainingRegulationService{public function getApplicableRequirements():array{return['Identificar necesidades según riesgos y características de la población','Mantener un programa documentado de capacitación en SST','Revisar el programa como mínimo anualmente','Registrar participación del COPASST o Vigía y de la alta dirección','Conservar acciones de mejora y trazabilidad'];}public function requiresAnnualProgramReview():bool{return true;}public function getReviewParticipants():array{return['copasst_or_vigia','senior_management'];}public function validateTrainingProgram(TrainingProgram $p):array{$errors=[];if(!$p->general_objective)$errors[]='Falta el objetivo general.';if(!$p->scope)$errors[]='Falta el alcance.';if($p->items()->count()===0)$errors[]='El programa no contiene actividades.';if($p->items()->whereNull('responsible_employee_id')->whereNull('external_responsible')->exists())$errors[]='Existen actividades sin responsable.';if($p->items()->whereNull('target_population_description')->exists())$errors[]='Existen actividades sin población definida.';return$errors;}public function validateProgramReview(TrainingProgram $p):array{$review=$p->reviews()->latest('review_date')->first();$errors=[];if(!$review)$errors[]='Debe registrar la revisión del programa.';elseif(!$review->copasst_or_vigia_participation)$errors[]='Debe documentar participación del COPASST o Vigía.';if(!$review?->senior_management_participation)$errors[]='Debe documentar participación de alta dirección.';return$errors;}public function getApplicableMinimumStandards():array{return['Programa de capacitación anual en promoción y prevención','Inducción y reinducción en SST'];}public function getRequiredEvidenceTypes():array{return['program_document','review_record'];}}
